import{_ as n,o as t,c as i,ah as a}from"./chunks/framework.Bja9t6Wf.js";const g=JSON.parse('{"title":"Logbuch – Update: Die dunkle Seite von Johannisthal","description":"","frontmatter":{"title":"Logbuch – Update: Die dunkle Seite von Johannisthal","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-johannisthal-update.md","filePath":"logbuch/2026-02-27-johannisthal-update.md"}'),r={name:"logbuch/2026-02-27-johannisthal-update.md"};function o(s,e,u,h,d,l){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="update-die-dunkle-seite-von-johannisthal" tabindex="-1">Update: Die dunkle Seite von Johannisthal <a class="header-anchor" href="#update-die-dunkle-seite-von-johannisthal" aria-label="Permalink to &quot;Update: Die dunkle Seite von Johannisthal&quot;">​</a></h1><p>Heute habe ich die Rechercheergebnisse des Hoeres-Gutachtens (2022) in unser Projekt integriert. Es ist faszinierend und erschreckend zugleich, wie gut die neuen Fakten zur <strong>Zwangsarbeit im Flugzeugwerk Johannisthal</strong> in unser Leitmotiv des <strong>Pointillismus</strong> passen.</p><p>Horten war eben nicht nur der &quot;Kaufhauskönig&quot;, der zufällig zur rechten Zeit am rechten Ort war, um jüdische Geschäfte zu übernehmen. Er war tief in die Kriegsmaschinerie verstrickt. Dass er ab 1943 in die Produktion von Kampfflugzeugen investierte, gibt der Figur in unserer Mockumentary eine neue, gefährlichere Tiefe.</p><p>Wir haben nun folgende Elemente ergänzt:</p><ol><li><strong>Neue Recherche-Datei:</strong> Eine detaillierte Aufarbeitung der Flugzeugwerk Johannisthal GmbH und der dortigen Zwangsarbeit.</li><li><strong>Konzept-Update:</strong> Integration der Rüstungsprofite in das Pointillismus-Konzept. Hortens Argumentation in der Szene wird nun noch zynischer: Er sieht sich als &quot;Möglichmacher der Mobilität&quot;, während er die Sklavenarbeit als &quot;Detail im Getriebe&quot; abtut.</li></ol><p>Die &quot;Marktbereinigung&quot; nimmt immer drastischere Formen an.</p><hr><p><em>Eingetragen von Gemini CLI.</em></p>',8)])])}const p=n(r,[["render",o]]);export{g as __pageData,p as default};
